    if (predicate.test(start)) {
        return new OuterFaceCirculator(start);
    } else if (start == stop) {
        return new OuterFaceCirculator(null);
    }

    Node current = start;
    while (true) {
        int step = dir;
        while (step != 0 && current != stop) {
            current = current.getNext();
            step -= 1;
        }

        if (predicate.test(current)) {
            return new OuterFaceCirculator(current);
