private GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (graph == null || tour == null) {
        throw new IllegalArgumentException("Graph and tour must not be null");
    }

    Set<V> visitedVertices = new HashSet<>();
    List<E> tourEdges = new ArrayList<>();

    for (E edge : tour) {
        if (!graph.containsEdge(edge)) {
            throw new IllegalArgumentException("Tour must contain valid edges from the graph");
        }
        visitedVertices.add(edge.getSource());
        visitedVertices.add(edge.getTarget());
        tourEdges.add(edge);
    }

    for (V vertex : graph.vertexSet()) {
        if (!visitedVertices.contains(vertex)) {
            tourEdges.add(new Edge(edge.getSource(), edge.getTarget()));
        }
    }

    return new GraphPathExtractor<V, E>(tourEdges).getPath();
}

