    // Perform validation on input parameters
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    // Initialize graph path object
    GraphPath<V, E> path = new GraphPath<>(graph);

    // Add edges from tour set to path
    for (E edge : tour) {
        path.addEdge(edge);
    }

    return path;
}

private GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    GraphPath<V, E> path = new GraphPath<>(graph);
    int i = 0;
    while (i < tour.size() - 1) {
        E edge = tour.get(i);
        V from = graph.getEdgeSource(edge);
        V to = graph.getEdgeTarget(edge);
        GraphPath<V, E> subPath = graph.getPath(from, to, edge);
        path = path.extendPath(subPath);
        i++;
    }
    return path;
}

