private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
	if (minLabel == 0) {
		throw new IllegalArgumentException("Invalid minLabel");
	}

	Set<Integer> verticesToReload = bucketsByLabel.get(minLabel);
	if (verticesToReload == null || verticesToReload.isEmpty()) {
		return;
	}

	List<Integer> newLabels = new ArrayList<>(verticesToReload.size());
	for (int i = 0; i < verticesToReload.size(); i++) {
		int vertex = verticesToReload.get(i);
		newLabels.add(0);
		labels.set(vertex, 0);
	}

	bucketsByLabel.set(minLabel, null);
	if (bucketsByLabel.size() > minLabel) {
		bucketsByLabel.subList(minLabel, bucketsByLabel.size()).clear();
	}

	bucketsByLabel.addAll(newLabels);
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Create a new bucket with label 0
    bucketsByLabel.add(new HashSet<Integer>());

    // Iterate over the vertices in the bucket with the minimum label
    for (int vertex : bucketsByLabel.get(minLabel)) {
        // Add the vertex to the new bucket with label 0
        bucketsByLabel.get(0).add(vertex);

        // Remove the vertex from the bucket with the minimum label
        bucketsByLabel.get(minLabel).remove(vertex);

        // Update the label of the vertex to 0
        labels.set(vertex, 0);
    }

    // Update the labeling of the dataset
    Relabel(labels, minLabel);

    // Clear the bucket with the minimum label
    bucketsByLabel.get(minLabel).clear();
}

