private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {

    // Check if the graph is null or the set of vertices is empty
    if (graph == null || vertices == null || vertices.isEmpty()) {
        throw new IllegalArgumentException("Graph or set of vertices cannot be null or empty");
    }

    // Check if all vertices are in the graph
    for (V vertex : vertices) {
        if (!graph.containsVertex(vertex)) {
            throw new IllegalArgumentException("Vertex " + vertex + " is not in the graph");
        }
    }

    // Check if the subgraph induced by the vertices is complete, i.e. a clique
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (vertex1 == vertex2) {
                continue;
            }
            // check if the edge between the two vertices is null
            if (graph.getEdge(vertex1, vertex2) == null) {
                return false;
            }
        }
    }

    // If we reach here, the subgraph is a clique
    return true;
}

