    // Check if the subgraph induced by the given vertices is complete
    // by checking if every vertex has an edge with every other vertex
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (!graph.hasEdge(vertex1, vertex2)) {
                return false;
            }
        }
    }
    return true;
}

