    // Check if the input graph is valid
    if (graph == null || vertices == null || vertices.isEmpty()) {
        throw new IllegalArgumentException("Invalid input graph or vertices");
    }

    // Check if the subgraph induced by the given vertices is complete
    boolean isClique = true;
    for (V vertex : vertices) {
        if (!graph.containsVertex(vertex)) {
            isClique = false;
            break;
        }
    }

    Set<E> edges = getAllEdges(graph, vertices);
    for (E edge : edges) {
        if (!graph.containsEdge(edge)) {
            isClique = false;
            break;
        }
    }

    return isClique;
}

