    String finalPath;
    if (path == null || relativePath == null) {
        throw new NullPointerException("Path or relative path cannot be null");
    }
    // Check if the relative path is blank
    if (relativePath.trim().equals("")) {
        finalPath = path;
    } else {
        // Check if the relative path has leading '/'
        if (relativePath.startsWith("/")) {
            finalPath = combinePath(path, relativePath);
        } else {
            finalPath = combinePath(path, "/" + relativePath);
        }
    }
    return finalPath;
}

public static String applyRelativePath(String path, String relativePath) {
    // Replace backslashes with forward slashes to ensure consistency
    path = path.replace("\\", "/");
    relativePath = relativePath.replace("\\", "/");

    // Handle if the relative path is absolute (starts with a forward slash)
    if (relativePath.startsWith("/")) {
        path = "";
    }

    // Split the path and relative path into their individual components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Loop through each component of the relative path
    for (String relativePathComponent : relativePathComponents) {
        // If the component is "." or "..", move to the previous directory
        if (relativePathComponent.equals(".") || relativePathComponent.equals("..")) {
            pathComponents = Arrays.copyOf(pathComponents, pathComponents.length - 1);
        } else {
            // Otherwise, add the component to the path
            pathComponents = Arrays.copyOf(pathComponents, pathComponents.length + 1);
            pathComponents[pathComponents.length - 1] = relativePathComponent;
        }
    }

    // Join the path components back together to form the new path
    return String.join("/", pathComponents);
}

