    if (path.isBlank() || relativePath.isBlank()) {
        throw new IllegalArgumentException("Path and relative path must not be blank.");
    }
    return Paths.get(path).resolve(relativePath).toAbsolutePath().toString();
}

public static String applyRelativePath(String path, String relativePath) {
    // Check if the input paths are null or empty
    if (path == null || path.isEmpty() || relativePath == null || relativePath.isEmpty()) {
        throw new IllegalArgumentException("Invalid input paths");
    }

    // Split the path and relative path into individual components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Create a new array to hold the combined path components
    String[] combinedPathComponents = new String[pathComponents.length + relativePathComponents.length];

    // Combine the path and relative path components
    System.arraycopy(pathComponents, 0, combinedPathComponents, 0, pathComponents.length);
    System.arraycopy(relativePathComponents, 0, combinedPathComponents, pathComponents.length, relativePathComponents.length);

    // Concatenate the components into a single string
    StringBuilder combinedPath = new StringBuilder();
    for (String component : combinedPathComponents) {
        combinedPath.append("/").append(component);
    }

    // Return the combined path
    return combinedPath.toString();
}

