public void abbreviate(final int nameStart, final StringBuffer buf) {
    // Append the first character of the name to the buffer
    buf.append(nameStart);

    // Iterate over the remaining characters in the name
    for (int i = nameStart + 1; i < name.length(); i++) {
        // If the current character is a period, skip it
        if (name.charAt(i) == '.') {
            continue;
        }
        // If the current character is a space, append an underscore to the buffer
        if (name.charAt(i) == ' ') {
            buf.append('_');
        } else {
            // Otherwise, append the character to the buffer
            buf.append(name.charAt(i));
        }
    }
}

